sys_ux_client_script.required_translations:
[
    {
        "message": "Please select Script to Install"
    },
    {
        "message": "Custom Script Installed Succesfully"
    },
    {
        "message": "Unable to Install Scripts"
    },
    {
        "message": "Something went wrong"
    }
]

sys_ux_client_script.script:
async function handler({ api, event, helpers, imports }) { 
    // Validate and log the helpers.snHttp object
    console.log("snHttp object: clicked", helpers.snHttp);
    // var ga = new GlideAjax('HelloWorld');
    if (!helpers.snHttp || typeof helpers.snHttp !== "function") {
        console.error("Error: helpers.snHttp is not properly initialized or is not callable.");
        return;
    }

    var scripts = api.state?.selectedScript?.scripts

    if(!scripts){
         api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'warning',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Please select Script to Install'),
                        action: { type: 'dismiss' }
                    }
                ]
            });
             return ;
    }

    var updatesets=[]
     scripts.map((e)=>{
updatesets.push("SAMImplementationCustomScript"+ e )
    })


        console.log("Request payload being sent:", updatesets);

        try {
            // Use snHttp to send the API request
            const response = await helpers.snHttp(
                "/api/985627/commit_update_set", // API endpoint
                {
                    method: "POST", // HTTP method
                    headers: {
                        "Content-Type": "application/json"
                    },
                    body: JSON.stringify({
        update_set_name: updatesets
    }) // Pass the request payload
                }
            );

            // Log the response for verification
            console.log("Response status:", response?.response?.result?.success);
            console.log("Response body:", response);

            // Process the API response
            if (response.status == 200 ||response.response.result.status == "success") {
                console.log(
                    `Success: Property  updated successfully.`,
                    response.result
                );

                  api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'positive',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Custom Script Installed Succesfully'),
                        action: { type: 'dismiss' }
                    }
                ]
            });


            } else {
                console.error(
                    `Error: Failed to update property `,
                    response
                );

                var errResponse = response?.response?.result.filter((e)=>{
                    return e.status == "error"
                })
                console.log("err res",errResponse.map(item => item.updateSetName).join(", "))

               api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'critical',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Unable to Install Scripts' + errResponse.map(item => item.updateSetName.replace("SAMImplementationCustomScript", "").trim()).join(", ") ),
                        action: { type: 'dismiss' }
                    }
                ]
            });

            }
        } catch (error) {
            // Handle any errors in the API call
            console.error(`Error updating property `, error?.error?.statusText);

            api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
                items: [
                    {
                        id: 'alert2',
                        status: 'critical',
                        icon: 'info-circle-outline',
                        content: await helpers.translate('Something went wrong'),
                        action: { type: 'dismiss' }
                    }
                ]
            });

            if (error.response) {
                console.error("Error response:", error.response);
            } else if (error.data) {
                console.error("Error data:", error.data);
            }
        }
    }
